#pragma once

#include <span>

#include <Veng/Veng.h>
#include <Veng/Result.h>
#include <Veng/Cook/Types.h>

namespace Veng::Cook
{
    /// @brief The most levels of detail a cooked mesh carries, level 0 included.
    inline constexpr u32 MaxMeshLodLevels = 8;

    /// @brief One coarser level as a `*.mesh.json` declares it.
    ///
    /// A level is generated by simplifying level 0 unless it names a Model, in which case that
    /// model's geometry is the level.
    struct MeshLodLevelSource
    {
        /// @brief Generated: the target triangle count as a fraction of level 0's.
        f32 Ratio = 0.5f;
        /// @brief Generated: the largest simplification error allowed, as a fraction of the mesh's
        ///        bounding diameter; the simplifier stops short of Ratio rather than exceed it.
        f32 MaxError = 1.0f;
        /// @brief The authored switch threshold (see CookedMeshLod::ScreenSize), or none to derive one.
        optional<f32> ScreenSize;
        /// @brief Authored: the model file, relative to the `*.mesh.json`; empty for a generated level.
        string Model;
        /// @brief Authored: the base submesh each of the model's meshes maps to, in model order, or
        ///        none to map by material name.
        optional<vector<u32>> SubMeshes;

        /// @brief Whether the level is an authored model rather than a simplification.
        [[nodiscard]] bool IsAuthored() const { return !Model.empty(); }
    };

    /// @brief A mesh's level-of-detail configuration (the `*.mesh.json` `"lod"` key).
    struct MeshLodSource
    {
        /// @brief Whether the mesh cooks any level beyond level 0.
        bool Enabled = false;
        /// @brief The coarser levels, in order (level 1 first).
        vector<MeshLodLevelSource> Levels;
        /// @brief The projected error, as a fraction of the view height, a derived threshold allows.
        f32 ScreenError = 0.001f;
        /// @brief How strongly the simplifier preserves vertex normals against position error.
        f32 NormalWeight = 0.5f;
    };

    /// @brief Reads a `*.mesh.json`'s `"lod"` key.
    ///
    /// Absent or false disables levels; true enables the default three generated levels (ratios
    /// one half, one quarter, one eighth); an object configures them. Unknown keys, out-of-range
    /// values and a malformed level are errors.
    /// @param meshJson The parsed `*.mesh.json`.
    /// @return The configuration, or an error naming the offending key.
    [[nodiscard]] Result<MeshLodSource> ParseMeshLodSource(const json& meshJson);

    /// @brief One built level: an index list per base submesh, plus how it was made.
    struct BuiltMeshLod
    {
        /// @brief Per base submesh, the level's indices into the shared vertex buffer.
        vector<vector<u32>> SubMeshIndices;
        /// @brief Simplification error as a fraction of the bounding diameter; 0 when authored.
        f32 Error = 0.0f;
        /// @brief The configured threshold, or none to derive one.
        optional<f32> ScreenSize;
        /// @brief Whether the level is an authored model.
        bool Authored = false;
    };

    /// @brief One base submesh's range in the level-0 index list.
    struct MeshLodSubMeshRange
    {
        /// @brief First index.
        u32 IndexOffset = 0;
        /// @brief Number of indices.
        u32 IndexCount = 0;
    };

    /// @brief The level-0 geometry a generated level simplifies, read in place.
    struct MeshLodGeometry
    {
        /// @brief The first vertex's position (three floats), strided by Stride.
        const f32* Positions = nullptr;
        /// @brief The first vertex's normal (three floats), strided by Stride.
        const f32* Normals = nullptr;
        /// @brief Number of vertices the indices may reference.
        usize VertexCount = 0;
        /// @brief Byte stride between consecutive vertices.
        usize Stride = 0;
        /// @brief The level-0 index list.
        std::span<const u32> Indices;
        /// @brief Each base submesh's level-0 range.
        std::span<const MeshLodSubMeshRange> SubMeshes;
        /// @brief The level-0 bounding diameter the error is measured against.
        f32 Diameter = 0.0f;
    };

    /// @brief Simplifies every base submesh of level 0 into one coarser level.
    ///
    /// Each submesh simplifies on its own, so materials and the submesh table survive, with its
    /// open borders locked — the edges it shares with a neighbouring submesh among them, so the
    /// level does not crack where two materials meet. Normals weigh in as attributes. The level's
    /// error is the largest any submesh reached.
    /// @param geometry     Level 0.
    /// @param level        The level's ratio and error bound.
    /// @param normalWeight How strongly normals are preserved.
    /// @return The level.
    [[nodiscard]] BuiltMeshLod SimplifyMeshLod(const MeshLodGeometry& geometry,
                                               const MeshLodLevelSource& level, f32 normalWeight);

    /// @brief Total triangles a level draws across its submeshes.
    [[nodiscard]] u32 CountTriangles(const BuiltMeshLod& level);

    /// @brief Resolves each level's switch threshold, level 1 first.
    ///
    /// A configured threshold is taken as given and must descend from the one before it. A
    /// generated level's derived threshold is the screen size at which its error projects to
    /// ScreenError — screenError / error, capped at 1 (a mesh as tall as the view draws level 0) —
    /// and an authored level's is half its predecessor's; a derived threshold is clamped not to
    /// exceed the one before it.
    /// @param levels      The built levels, level 1 first.
    /// @param screenError The projected error a derived threshold allows.
    /// @return The thresholds, or an error naming a configured threshold that does not descend.
    [[nodiscard]] Result<vector<f32>>
    ResolveMeshLodScreenSizes(std::span<const BuiltMeshLod> levels, f32 screenError);
}
